"""Minimal offline shim of `hypothesis.strategies`.

Provides just enough of the `integers` strategy to support property-based
tests in this repository via the local `hypothesis` shim package.
"""
import random


class IntegersStrategy:
    def __init__(self, min_value=None, max_value=None):
        self.min_value = min_value if min_value is not None else -1000
        self.max_value = max_value if max_value is not None else 1000

    def example(self, rng: random.Random = None):
        rng = rng or random
        return rng.randint(self.min_value, self.max_value)


def integers(min_value=None, max_value=None):
    return IntegersStrategy(min_value=min_value, max_value=max_value)

