def given(*arg_strategies, **kwarg_strategies):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            rng = random.Random(0)
            for _ in range(_NUM_EXAMPLES):
                gen_args = [s.example(rng) for s in arg_strategies]
                gen_kwargs = {k: s.example(rng) for k, s in kwarg_strategies.items()}
                func(*args, *gen_args, **kwargs, **gen_kwargs)
        # Remove hypothesis-generated parameters from the signature so
        # pytest does not try to resolve them as fixtures.
        wrapper.__wrapped__ = func
        try:
            import inspect
            sig = inspect.signature(func)
            n_pos = len(arg_strategies)
            params = list(sig.parameters.values())
            kept = params[: len(params) - n_pos - len(kwarg_strategies)] if (n_pos or kwarg_strategies) else params
            wrapper.__signature__ = sig.replace(parameters=kept)
        except (TypeError, ValueError):
            pass
        return wrapper
    return decorator

